   136  /* send a CASIC message.
   137   * calculate checksums, etc.
   138   */
   139  bool casic_write(struct gps_device_t * session,
   140                  unsigned int msg_class, unsigned int msg_id,
   141                  const unsigned char *msg, size_t payload_len)
   142  {
   143      ssize_t count;
   144      bool ok;
   145      unsigned checksum;
   146
   147      // do not write if -b (readonly) option set
   148      // "passive" handled earlier
   149      if (session->context->readonly) {
   150          return true;
   151      }
   152
   153      if ((sizeof(session->msgbuf) - 10) <= payload_len ||
   154          2048 < payload_len) {
   155          GPSD_LOG(LOG_WARN, &session->context->errout,
   156                   "=> GPS: CASIC class: %02x, id: %02x, len: %zd TOO LONG!\n",
   157                   msg_class, msg_id, payload_len);
   158      }
   159      if (0 != (payload_len % 4)) {
   160          GPSD_LOG(LOG_WARN, &session->context->errout,
   161                   "=> GPS: CASIC class: %02x, id: %02x, len: %zd UN ALIGNED!\n",
   162                   msg_class, msg_id, payload_len);
   163      }
   164
   165      session->msgbuf[0] = 0xba;
   166      session->msgbuf[1] = 0xce;
   167
   168      session->msgbuf[2] = payload_len & 0xff;
   169      session->msgbuf[3] = (payload_len >> 8) & 0xff;
   170      session->msgbuf[4] = msg_class;
   171      session->msgbuf[5] = msg_id;
   172
   173      if (NULL != msg &&
   174          0 < payload_len) {
   175          (void)memcpy(&session->msgbuf[CASIC_PREFIX_LEN], msg, payload_len);
   176      }
   177
   178      checksum = casic_checksum((unsigned char *)session->msgbuf + 2,
   179                                payload_len + 4);
   180      putle32(session->msgbuf, payload_len + 6, checksum);
   181
   182      session->msgbuflen = payload_len + 10;
   183
   184      GPSD_LOG(LOG_PROG, &session->context->errout,
   185               "=> GPS: CASIC: class: %02x, id: %02x, len: %zd, csum: %04x\n",
   186               msg_class, msg_id, payload_len,
   187               checksum);
   188      count = gpsd_write(session, session->msgbuf, session->msgbuflen);
   189      ok = (count == (ssize_t) session->msgbuflen);
   190      return ok;
   191  }
