   269  /* msg_decode() -- dispatch all message types to proper decoder
   270   */
   271  static gps_mask_t msg_decode(struct gps_device_t *session,
   272                               unsigned char *buf, size_t payload_len)
   273  {
   274      unsigned msgid = getbes16(buf, 4);
   275      gps_mask_t mask = 0;
   276      size_t needed_len;
   277      const char *msg_name;
   278      gps_mask_t (* p_decode)(struct gps_device_t *, unsigned char *, size_t);
   279
   280      switch (msgid) {
   281      case ACK_NAK:
   282          needed_len = 4;
   283          msg_name = "ACK-NAK";
   284          p_decode = msg_ack_nak;
   285          break;
   286      case ACK_ACK:
   287          needed_len = 4;
   288          msg_name = "ACK-ACK";
   289          p_decode = msg_ack_ack;
   290          break;
   291      case CFG_PRT:
   292          msg_name ="CFG-PRT";
   293          needed_len = 8;
   294          p_decode = msg_cfg_prt;
   295          break;
   296      case MON_VER:
   297          msg_name ="MON-VER";
   298          needed_len = 64;
   299          p_decode = msg_mon_ver;
   300          break;
   301      default:
   302          msg_name ="UNK-UNK";
   303          needed_len = 0;
   304          p_decode = NULL;
   305          break;
   306      }
   307      if (needed_len > payload_len) {
   308          GPSD_LOG(LOG_WARN, &session->context->errout,
   309                   "CASIC: %s: runt payload len %zd need %zd\n",
   310                   msg_name, payload_len, needed_len);
   311          return 0;
   312      }
   313      if (NULL == p_decode) {
   314          GPSD_LOG(LOG_WARN, &session->context->errout,
   315                   "CASIC: Unsupported/unknown %s(%02x)-%02x payload_len %zd\n",
   316                   val2str((msgid >> 8) & 0xff, vclass),
   317                   (msgid >> 8) & 0xff,
   318                   msgid & 0xff, payload_len);
   319          return 0;
   320      }
   321      mask = p_decode(session, &buf[CASIC_PREFIX_LEN], payload_len);
   322      return mask;
   323  }
