   325  static gps_mask_t casic_parse(struct gps_device_t * session,
   326                                unsigned char *buf, size_t len)
   327  {
   328      size_t payload_len;
   329      gps_mask_t mask = 0;
   330      int class, id;
   331
   332      /* Minimum packet size is 10: header (2), length (2), Message ID
   333      *  (2), payload (0), and checksum (4).  The packetizer should
   334      *  already guarantee this to protect against malicious fuzzing. */
   335      if (10 > len) {
   336          GPSD_LOG(LOG_WARN, &session->context->errout,
   337                   "CASIC: runt message len %zu\n", len);
   338          return 0;
   339      }
   340
   341      // extract payload length, check against actual length
   342      payload_len = getles16(buf, 2);
   343
   344      if ((len - 10) != payload_len) {
   345          GPSD_LOG(LOG_WARN, &session->context->errout,
   346                   "CASIC: len (%zu) does not match payload (%zu) + 10\n",
   347                   len, payload_len);
   348          return 0;
   349      }
   350
   351      class = buf[4];
   352      id = buf[5];
   353
   354      GPSD_LOG(LOG_PROG, &session->context->errout,
   355               "CASIC: %s(%02x)-%02x\n",
   356               val2str(class, vclass), class, id);
   357
   358      mask = msg_decode(session, buf, payload_len);
   359
   360      return mask;
   361  }
