   363  static gps_mask_t parse_input(struct gps_device_t *session)
   364  {
   365      if (CASIC_PACKET == session->lexer.type) {
   366          return casic_parse(session, session->lexer.outbuffer,
   367                             session->lexer.outbuflen);
   368      }
   369      // a comment, JSON, or NMEA 0183
   370      return generic_parse_input(session);
   371  }
