   383  static void event_hook(struct gps_device_t *session, event_t event)
   384  {
   385      if (session->context->readonly) {
   386          return;
   387      }
   388      if (EVENT_IDENTIFIED == event) {
   389          return;
   390      }
   391      // We would like MON-VER but it at least sometimes doesn't work.
   392      (void)casic_write(session, CASIC_MON, 0x04, NULL, 0);
   393      // Port configuration seems to work.
   394      (void)casic_write(session, CASIC_CFG, 0x00, NULL, 0);
   395  }
